const j = $input.first().json;
const SENSITIVE = /(api[_-]?key|token|authorization|password|secret|cookie|image_base64|base64)/i;
const scrub = (s) => String(s).replace(/AIza[0-9A-Za-z_\-]{20,}/g, '[REDACTED]').replace(/Bearer\s+[A-Za-z0-9._\-]+/gi, 'Bearer [REDACTED]');
const clean = (v, depth = 0) => {
  if (v === null || v === undefined) return v;
  if (typeof v === 'string') { const s = scrub(v); return s.length > 500 ? s.slice(0, 500) + '...[cat ' + s.length + ' ky tu]' : s; }
  if (typeof v !== 'object') return v;
  if (depth >= 4) return '[...]';
  if (Array.isArray(v)) return v.slice(0, 10).map((x) => clean(x, depth + 1));
  const out = {};
  for (const [k, val] of Object.entries(v)) out[k] = SENSITIVE.test(k) ? '[REDACTED]' : clean(val, depth + 1);
  return out;
};

let n;
if (j.execution && j.workflow) {            // goi boi Error Trigger
  const e = j.execution;
  n = {
    source: j.workflow.name || 'unknown', source_workflow_id: j.workflow.id || null, execution_id: e.id || null,
    failed_node: e.lastNodeExecuted || null, severity: 'error', error_code: 'WORKFLOW_EXECUTION_ERROR',
    message: (e.error && e.error.message) || 'Loi khong ro', request_id: null,
    context: { mode: e.mode || null, url: e.url || null, stack: e.error && e.error.stack ? String(e.error.stack).split('\n').slice(0, 5).join('\n') : null }
  };
} else {                                    // goi tuong minh
  const rid = Number(j.request_id);
  n = {
    source: j.source || 'unknown', source_workflow_id: j.source_workflow_id || null, execution_id: j.execution_id || null,
    failed_node: j.failed_node || null, severity: ['info', 'warning', 'error', 'critical'].includes(j.severity) ? j.severity : 'error',
    error_code: j.error_code || 'EXPLICIT_ERROR', message: j.message || 'Loi khong ro',
    request_id: Number.isInteger(rid) && rid > 0 ? rid : null, context: j.context || null
  };
}
n.message = scrub(n.message).slice(0, 2000);
n.context = clean(n.context);
return [{ json: {
  operation: 'log_session',
  data: {
    request_id: n.request_id, user_command: 'system_error:' + n.source,
    ai_analysis_json: { severity: n.severity, error_code: n.error_code, source_workflow_id: n.source_workflow_id, execution_id: n.execution_id, failed_node: n.failed_node, context: n.context },
    status: 'error', error_message: '[' + n.error_code + '] ' + n.message
  },
  normalized: n
} }];

const n = $('Normalize Error').first().json.normalized;
const r = $input.first().json;
const logged = !!(r && r.success === true);
return [{ json: { logged, log_id: logged && r.rows[0] ? r.rows[0].id : null, source: n.source, error_code: n.error_code, severity: n.severity, execution_id: n.execution_id, log_error: logged ? null : (r && r.error ? String(r.error) : 'Khong ghi duoc session_logs') } }];
